/**
 * @method
 * @name MxDataSet_dep_part_OnFilter
 * @description Mx Data Set dep part On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_dep_part_OnFilter = function(row) {
    try {
        if (scwin.jheader !== "" && scwin.jheader !== "0000") {
            if (MxDataSet_dep_part.getCellData(row, "UP_DEP_CD") === scwin.jheader || MxDataSet_dep_part.getCellData(row, "UP_DEP_CD") === "0000") {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40008.MxDataSet_dep_part_OnFilter" });
    }
};

/**
 * @method
 * @name MxDataSet_dep_team_OnFilter
 * @description Mx Data Set dep team On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_dep_team_OnFilter = function(row) {
    try {
        if (scwin.jheader !== "" && scwin.jheader !== "0000" && (scwin.jpart === "" || scwin.jpart === "0000")) {
            // 본부에서 변경한 경우
            const len_jheader = scwin.jheader.substring(0, 1);
            if (MxDataSet_dep_team.getCellData(row, "DEP_CD").substring(0, 1) === len_jheader || MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") === "0000") {
                return true;
            } else {
                return false;
            }
        }
        if (scwin.jheader !== "" && scwin.jheader !== "0000" && (scwin.jpart !== "" || scwin.jpart !== "0000")) {
            if (MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") === scwin.jpart || MxDataSet_dep_team.getCellData(row, "UP_DEP_CD") === "0000") {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40008.MxDataSet_dep_team_OnFilter" });
    }
};

